refundOrder(orderId, items, { date, restock = true }) {
  const o = this.getOrder(orderId);
  if (o.status !== 'placed' && o.status !== 'partially_refunded') throw new OrderError(`Order ${orderId} cannot be cancelled in status ${o.status}`);
  // date validation
  if (typeof date !== 'string' || !DATE_RE.test(date) || date < o.date) {
    throw new RefundError('Invalid refund date');
  }
  // items
  const itemMap = {};
  for (const it of items) {
    if (!Number.isInteger(it.qty) || it.qty <= 0) throw new RefundError(`Invalid quantity for ${it.sku}`);
    itemMap[it.sku] = (itemMap[it.sku] ?? 0) + it.qty;
  }
  // merge same SKU
  for (const l of o.lines) {
    if (!itemMap.has(l.sku)) throw new RefundError(`SKU ${l.sku} not in order`);
    itemMap[l.sku] += l.qty;
  }
  // validate per-line refunded quantity
  for (const l of o.lines) {
    const remaining = l.qty - l.refundedQty;
    if (itemMap[l.sku] > remaining) throw new RefundError(`Refund exceeds available units for ${l.sku}`);
  }
  // compute running totals
  for (const l of o.lines) {
    if (l.qty === l.refundedQty) {
      l.refundedNetCents = l.netCents;
      l.refundedTaxCents = l.taxCents;
      l.refundedTotalCents = l.totalCents;
    } else {
      l.refundedNetCents = roundHalfAwayFromZero(l.netCents * itemMap[l.sku] / l.qty);
      l.refundedTaxCents = roundHalfAwayFromZero(l.taxCents * itemMap[l.sku] / l.qty);
      l.refundedTotalCents = l.refundedNetCents + l.refundedTaxCents;
    }
  }
  // restock
  if (restock) {
    for (const l of o.lines) this.inventory.release(l.sku, l.refundedQty);
  }
  // status
  const allRefunded = o.lines.every(l => l.refundedQty === l.qty);
  o.status = allRefunded ? 'refunded' : 'partially_refunded';
  // refund record
  const refundRecord = {
    id: `R${String(this.nextOrderNo()).padStart(4, '0')}`,
    orderId: o.id,
