    totalCents: o.lines.reduce((a, l) => a + l.refundedTotalCents, 0),
  };
  this.orders.get(o.id).refunds = this.orders.get(o.id).refunds || [];
  this.orders.get(o.id).refunds.push(refundRecord);
  return refundRecord;
}
