```js
function allocate(totalCents, weights) {
  const sum = weights.reduce((a, b) => a + b, 0);
  if (sum === 0) return weights.map(() => 0);
  const n = weights.length;
  const floors = weights.map((w) => Math.floor((totalCents * w) / sum));
  let remainder = totalCents - floors.reduce((a, b) => a + b, 0);
  // Build list of (index, fractional remainder) for tie-breaking
  const indexed = [];
  for (let i = 0; i < n; i++) {
    const rem = (totalCents * weights[i] / sum) - floors[i];
    if (rem > 0) indexed.push({ index: i, rem });
  }
  // Sort by remainder descending, then index ascending
  indexed.sort((a, b) => b.rem - a.rem || a.index - b.index);
  for (let i = 0; i < remainder && i < indexed.length; i++) {
    floors[indexed[i].index] += 1;
  }
  return floors;
}
