const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

/** Order life cycle (SPEC section 7). */
class OrderService {
  constructor({ catalog, inventory, coupons = [] }) {
    this.catalog = catalog;
    this.inventory = inventory;
    this.coupons = new Map(coupons.map((c) => [c.code, c]));
    this.orders = new Map();
    this.nextOrderNo = 1;
    this.couponUsage = new Set(); // "customerId:CODE"
    this.nextRefundNo = 1;
  }

  _mergeLines(lines) {
    if (!Array.isArray(lines) || lines.length === 0) throw new OrderError('An order needs at least one line');
    const merged = new Map();
    for (const { sku, qty } of lines) {
      if (!Number.isInteger(qty) || qty <= 0) throw new OrderError(`Invalid quantity for ${sku}: ${qty}`);
      if (!this.catalog.has(sku)) throw new OrderError(`Unknown SKU: ${sku}`);
      if (!this.catalog.get(sku).active) throw new OrderError(`Product ${sku} is not available`);
      merged.set(sku, (merged.get(sku) ?? 0) + qty);
    }
    return [...merged].map(([sku, qty]) => ({ sku, qty }));
  }

  createOrder({ customerId, lines, couponCode = null, date }) {
    if (typeof customerId !== 'string' || customerId === '') throw new OrderError('customerId is required');
    if (typeof date !== 'string' || !DATE_RE.test(date)) throw new OrderError('date must be YYYY-MM-DD');
    const merged = this._mergeLines(lines);

    let coupon = null;
    if (couponCode !== null) {
      coupon = this.coupons.get(couponCode);
      if (!coupon) throw new CouponError(`Unknown coupon: ${couponCode}`);
      const subtotalCents = merged.reduce((a, l) => a + this.catalog.get(l.sku).priceCents * l.qty, 0);
      assertCouponUsable(coupon, { date, subtotalCents, customerId, usedBy: this.couponUsage });
    }

    // Reserve all lines atomically; rollback on failure
    try {
      for (const l of merged) this.inventory.reserve(l.sku, l.qty);
    } catch (e) {
      if (e instanceof InventoryError) {
        for (const l of merged) this.inventory.release(l.sku, l.qty);
      }
      throw e;
    }

    const priced = priceLines(merged, this.catalog, coupon);
    const id = `O${String(this.nextOrderNo++).padStart(4, '0')}`;
    const order = { id, customerId, date, couponCode, status: 'placed', lines: priced, totals: summarize(priced), refunds: [] };
    if (coupon) this.couponUsage.add(`${customerId}:${coupon.code}`);
    this.orders.set(id, order);
    return order;
  }

  getOrder(id) {
    const o = this.orders.get(id);
    if (!o) throw new OrderError(`Unknown order: ${id}`);
    return o;
  }

  cancelOrder(id) {
    const o = this.getOrder(id);
    if (o.status !== 'placed') throw new OrderError(`Order ${id} cannot be cancelled in status ${o.status}`);
    for (const l of o.lines) this.inventory.release(l.sku, l.qty);
    o.status = 'cancelled';
    if (o.couponCode) this.couponUsage.delete(`${o.customerId}:${o.couponCode}`);
    return o;
  }

  listOrders() {
    return [...this.orders.values()];
  }

  refundOrder(orderId, items, { date, restock = true }) {
    const o = this.getOrder(orderId);
    if (o.status !== 'placed' && o.status !== 'partially_refunded') {
      throw new RefundError(`Cannot refund order ${orderId}: status ${o.status}`);
    }
    // Validate date
    if (typeof date !== 'string' || !DATE_RE.test(date) || date < o.date) {
      throw new RefundError(`Invalid refund date: ${date}`);
    }
    // Validate items
    const itemMap = {};
    for (const { sku, qty } of items) {
      if (!Number.isInteger(qty) || qty <= 0) {
        throw new RefundError(`Invalid quantity for ${sku}: ${qty}`);
      }
      itemMap[sku] = (itemMap[sku] ?? 0) + qty;
    }
    // Merge same SKU lines
    const mergedItems = [...new Map(Object.entries(itemMap).map(([sku, qty]) => [sku, qty]))];
    for (const line of o.lines) {
      if (!mergedItems.has(line.sku)) {
        throw new RefundError(`SKU ${line.sku} not in order`);
      }
      const refundedQty = mergedItems.get(line.sku);
      if (refundedQty > line.qty) {
        throw new RefundError(`Refund quantity exceeds available units for ${line.sku}`);
      }
    }

    // Calculate per-line refunds
    const refundRecords = [];
    for (const line of o.lines) {
      let refundedNetCents, refundedTaxCents;
      if (refundedQty === undefined || refundedQty === 0) {
        refundedNetCents = 0;
        refundedTaxCents = 0;
      } else if (refundedQty === line.qty) {
        // All units refunded
        refundedNetCents = line.netCents;
        refundedTaxCents = line.taxCents;
      } else {
        refundedNetCents = roundHalfAwayFromZero(line.netCents * refundedQty / line.qty);
        refundedTaxCents = roundHalfAwayFromZero(line.taxCents * refundedQty / line.qty);
      }
      line.refundedQty = refundedQty;
      line.refundedNetCents = refundedNetCents;
      line.refundedTaxCents = refundedTaxCents;
      if (refundedQty > 0) {
        line.totalCents = refundedNetCents + refundedTaxCents;
      }
      const record = {
        id: `R${String(this.nextRefundNo++).padStart(4, '0')}`,
        orderId,
        date,
        lines: [{ sku: line.sku, qty: refundedQty, netCents: refundedNetCents, taxCents: refundedTaxCents, totalCents: line.totalCents }],
        totalCents: refundedNetCents + refundedTaxCents,
      };
      refundRecords.push(record);
    }

    if (restock) {
      for (const line of o.lines) {
        this.inventory.release(line.sku, line.qty);
      }
    }

    if (refundRecords.length === o.lines.length) {
      o.status = 'refunded';
    } else {
      o.status = 'partially_refunded';
    }
    o.refunds.push(...refundRecords);
    return refundRecords[0];
  }
}

module.exports = { OrderService, OrderError };
